diffs.patch:
Index: docs/library.html
===================================================================
--- docs/library.html	
+++ docs/library.html	
@@ -1,1641 +1,1658 @@
 <!DOCTYPE html>
 <html lang="ru">
 <head>
 <meta charset="utf-8">
 <meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">
 <meta name="theme-color" content="#0d0d12">
 <link rel="manifest" href="manifest.webmanifest">
 <title>Symbiosis</title>
 <style>
   :root {
     --bg:#101014; --card:#16161c; --line:#2a2a36; --text:#ececf4;
     --dim:#8b8b9c; --pink:#ff2d78; --cyan:#3ee0d4; --on:#1c1c24;
   }
   * { box-sizing:border-box; -webkit-tap-highlight-color:transparent; }
   html, body { height:100%; margin:0; }
   body {
     background:var(--bg); color:var(--text);
     font:15px/1.35 -apple-system,"Segoe UI",Roboto,sans-serif;
     display:flex; flex-direction:column;
     overflow:hidden;
     padding-top:48px;
     transition:background .2s ease, color .2s ease;
   }
   header {
     display:flex; align-items:center; gap:6px;
     padding:6px 12px 0;
   }
   header h1 { font-size:22px; font-weight:700; margin:0; flex:1; display:flex; align-items:center; gap:8px; }
   header h1 svg { width:28px; height:28px; flex:0 0 28px; }
   .boot {
     position:absolute; inset:0; z-index:20; background:#101014;
     display:flex; flex-direction:column; align-items:center; justify-content:center;
     transition:opacity .45s ease;
   }
   .boot.go { opacity:0; pointer-events:none; }
   .boot .mark { width:88px; height:88px; animation:spin-mark 1.1s ease-in-out infinite; }
   .boot p { color:var(--dim); margin:14px 0 0; font-size:13px; }
   @keyframes spin-mark {
     0% { transform:rotate(-8deg) scale(.92); }
     50% { transform:rotate(8deg) scale(1); }
     100% { transform:rotate(-8deg) scale(.92); }
   }
   .iconbtn {
     min-width:36px; height:36px; border-radius:12px; border:1px solid var(--line);
     background:#1c1c26; color:var(--text); font-size:13px; padding:0 9px;
     transition:transform .12s ease, background .12s ease, opacity .12s ease;
   }
   .iconbtn:active { transform:scale(.96); background:var(--on); }
   .search {
     margin:10px 12px 6px; display:flex; align-items:center; gap:10px;
     border:1px solid var(--line); border-radius:22px; padding:0 14px; height:42px;
   }
   .search input {
     flex:1; border:0; outline:0; background:transparent; color:var(--text);
     font:inherit; min-width:0;
   }
   .search input::placeholder { color:var(--dim); }
   .status {
     margin:0 12px 6px; border:1px solid var(--line); border-radius:12px;
     padding:8px 10px; font-size:12.5px; color:var(--dim);
   }
   .status .line { color:var(--text); font-weight:600; margin-bottom:4px; }
   .chips { display:flex; gap:6px; overflow-x:auto; padding-bottom:2px; }
   .chip {
     flex:0 0 auto; border:1px solid var(--line); border-radius:999px;
     padding:3px 10px; font-size:12px; color:var(--text);
   }
   .chip.tap { color:var(--cyan); }
   .list {
     flex:1; overflow:auto; padding:0 6px 110px;
     -webkit-overflow-scrolling:touch;
   }
   .game {
     display:flex; align-items:stretch; gap:12px;
     margin:6px; padding:8px; border-radius:16px; border:1px solid var(--line);
     background:var(--card);
     transition:background .12s ease, transform .12s ease, opacity .18s ease;
   }
   .game:active { background:var(--on); transform:scale(.985); }
   .thumb {
     width:64px; height:64px; border-radius:12px; flex:0 0 64px;
     background:linear-gradient(145deg,#2a1630,#16222a);
     overflow:hidden; display:flex; align-items:center; justify-content:center;
     color:var(--pink); font-size:20px;
     align-self:center;
   }
   .thumb img { width:100%; height:100%; object-fit:cover; display:block; }
   .meta { flex:1; min-width:0; align-self:center; }
   .title { font-weight:700; font-size:14px; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
   .sub { color:var(--dim); font-size:12px; margin-top:2px; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
   .stats { margin-top:3px; font-size:12px; color:var(--cyan); }
   .play { margin-right:8px; }
   .shot {
     width:72px; height:40px; border-radius:8px; flex:0 0 72px;
     background:#111; overflow:hidden; align-self:center;
   }
   .shot img { width:100%; height:100%; object-fit:cover; display:block; }
   .addons {
     flex:0 1 42%; max-width:46%; min-width:0;
     border-left:1px solid var(--line); padding:2px 0 2px 8px;
   }
   .addon-name { color:var(--cyan); font-size:11px; font-weight:600; }
   .addon-file {
     display:block; width:100%; text-align:left;
     background:transparent; border:0; color:var(--dim);
     font:11px/1.3 inherit; padding:3px 0;
     white-space:nowrap; overflow:hidden; text-overflow:ellipsis;
   }
   .empty { color:var(--dim); text-align:center; padding:40px 20px; }
   .fabs {
     position:absolute; right:16px; bottom:72px;
     display:flex; gap:8px; z-index:4;
   }
   .fab {
     height:48px; padding:0 16px; border:0; border-radius:24px;
     background:var(--pink); color:#fff; font:600 14px/48px inherit;
     transition:transform .12s ease, opacity .12s ease;
   }
   .fab:active { transform:scale(.97); }
   .fab.ghost {
     background:#1c1c26; color:var(--text); border:1px solid var(--line);
   }
   .bar {
     position:absolute; left:12px; right:12px; bottom:14px;
     border:1px solid var(--line); border-radius:12px;
     background:#16161c; padding:8px 12px; font-size:12.5px; color:var(--dim);
     z-index:4;
   }
   .bar b { color:var(--text); }
   .sheet {
     display:flex; position:absolute; inset:0; background:rgba(0,0,0,.55);
     z-index:6; align-items:flex-end;
     opacity:0; visibility:hidden; pointer-events:none;
     transition:opacity .18s ease, visibility .18s ease;
   }
   .sheet.on { opacity:1; visibility:visible; pointer-events:auto; }
   .sheet .box {
     width:100%; background:#14141a; border-radius:18px 18px 0 0;
     padding:16px 16px 24px; max-height:80%; overflow:auto;
     transform:translateY(18px);
     transition:transform .18s ease;
   }
   .sheet.on .box { transform:translateY(0); }
   .sheet h2 { margin:0 0 10px; font-size:16px; }
   .row { display:flex; gap:8px; flex-wrap:wrap; }
   button.ghost {
     background:transparent; color:var(--cyan); border:1px solid var(--line);
     border-radius:10px; padding:10px 12px; font:600 13px inherit;
     transition:transform .12s ease, background .12s ease;
   }
   button.ghost:active { transform:scale(.97); background:var(--on); }
   .note { color:var(--dim); font-size:12.5px; margin-top:8px; word-break:break-all; }
   .note pre {
     white-space:pre-wrap; word-break:break-word;
     margin:8px 0 0; font:12px/1.4 ui-monospace,monospace; color:var(--text);
   }
   .plug {
     border:1px solid var(--line); border-radius:12px;
     padding:8px 10px; margin:6px 0;
     display:flex; gap:8px; align-items:center;
   }
   .plug .nm { flex:1; min-width:0; }
   .plug .nm b { display:block; }
   .logline {
     border-top:1px solid var(--line); padding:7px 0;
     font-size:12.5px;
   }
   .logline .ok { color:var(--cyan); }
   .logline .bad { color:var(--pink); }
   .logline .wh { color:var(--dim); font-size:11px; margin-top:2px; }

   .tabs { display:flex; gap:6px; margin:8px 12px 0; }
   .tab {
     flex:1; height:36px; border-radius:12px; border:1px solid var(--line);
     background:#1c1c26; color:var(--dim); font:600 14px inherit;
     transition:background .15s ease, color .15s ease, transform .12s ease;
   }
   .tab.on { background:var(--on); color:var(--text); }
   .view { display:none; flex:1; min-height:0; flex-direction:column; overflow:hidden; }
   .view.on { display:flex; }
   .conv-list { flex:1; overflow:auto; padding:0 6px 110px; }
   .card {
     display:flex; gap:12px; align-items:center;
     margin:6px; padding:8px; border-radius:16px; border:1px solid var(--line);
     background:var(--card);
     transition:transform .12s ease, background .12s ease;
   }
   .card:active { transform:scale(.985); }
   .card .go { background:var(--pink); color:#fff; border:0; border-radius:10px; padding:8px 12px; font:600 13px inherit; }
   .card .bad { color:var(--pink); }
   .card .ok { color:var(--cyan); }

   .tools { display:flex; gap:6px; margin:0 12px 6px; overflow-x:auto; }
   .tools button {
     flex:0 0 auto; height:30px; border-radius:999px; border:1px solid var(--line);
     background:#1c1c26; color:var(--dim); font:600 12px inherit; padding:0 12px;
   }
   .tools button.on { background:var(--on); color:var(--text); }
   .tid { font:11px/1.3 ui-monospace,monospace; color:var(--dim); margin-top:2px; }
   .chip.x { padding-right:6px; }
   .chip .rm { color:var(--pink); margin-left:6px; border:0; background:transparent; font:700 13px inherit; }
   .tog { display:flex; gap:10px; align-items:center; border-top:1px solid var(--line); padding:8px 0; }
   .tog .nm { flex:1; min-width:0; }
   .tog .nm b { display:block; font-size:13px; }
   .tog .nm span { color:var(--dim); font-size:11.5px; }
   .sw {
     min-width:52px; height:30px; border-radius:999px; border:1px solid var(--line);
     background:#1c1c26; color:var(--dim); font:700 11px inherit;
   }
   .sw.on { background:var(--cyan); color:#062; border-color:transparent; }
   .res { display:flex; align-items:center; gap:8px; margin:8px 0; }
   .gallery { display:flex; gap:8px; overflow-x:auto; margin-top:8px; }
   .gallery img { height:72px; border-radius:8px; }

   #view-launch { min-height:0; }
   .rail-wrap {
     position:relative; flex:0 0 42%; min-height:160px;
     display:flex; align-items:center;
   }
   .rail {
     flex:1; min-width:0; height:100%;
     display:flex; align-items:center; gap:16px;
     overflow-x:auto; overflow-y:hidden;
     scroll-snap-type:x mandatory;
     -webkit-overflow-scrolling:touch;
     padding:8px 18vw;
     scrollbar-width:none;
   }
   .rail::-webkit-scrollbar { display:none; }
   .slide {
     flex:0 0 min(42vw, 220px); width:min(42vw, 220px); height:min(42vw, 220px);
     scroll-snap-align:center;
     border-radius:22px; overflow:hidden;
     background:linear-gradient(160deg,#2a1630,#16222a);
     border:1px solid var(--line);
     display:flex; align-items:center; justify-content:center;
     color:var(--pink); font-size:42px; font-weight:700;
     transform:scale(.88); opacity:.55;
     transition:transform .18s ease, opacity .18s ease, box-shadow .18s ease;
   }
   .slide.on { transform:scale(1); opacity:1; box-shadow:0 12px 40px rgba(0,0,0,.45); }
   .slide img { width:100%; height:100%; object-fit:cover; display:block; }
   .navb {
     position:absolute; top:50%; transform:translateY(-50%);
     z-index:3; width:40px; height:40px; border-radius:20px;
     border:1px solid var(--line); background:#1c1c26cc; color:var(--text);
     font:700 22px/40px inherit; padding:0;
   }
   .navb.l { left:8px; }
   .navb.r { right:8px; }
   .dock {
     flex:1 1 auto; min-height:0;
     margin:0 10px 10px; padding:10px 12px 12px;
     border:1px solid var(--line); border-radius:18px;
     background:#14141c;
     display:flex; flex-direction:column; overflow:hidden;
   }
   .dock-head { flex:0 0 auto; }
   .dock-body { flex:1 1 auto; min-height:0; overflow:auto; }
   .dock h2 { margin:0 0 2px; font-size:18px; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
   .dock .who { color:var(--dim); font-size:12px; margin-bottom:6px; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
+  /* Сколько игр в библиотеке всего: без этого карусель из одной плитки
+     читается как «у меня одна игра», а полосы прокрутки у рельса нет. */
+  .dock .pos { color:var(--cyan); font-size:12px; font-weight:700; margin-bottom:6px; }
   .facts { display:flex; flex-wrap:wrap; gap:6px; margin:6px 0; }
   .fact {
     border:1px solid var(--line); border-radius:10px;
     padding:6px 8px; flex:1 1 30%; min-width:28%; max-width:100%;
   }
   .fact b { display:block; font-size:11px; color:var(--dim); font-weight:600; }
   .fact span { display:block; font-size:13px; color:var(--text); overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }
   .dock .go {
     width:100%; height:44px; border:0; border-radius:14px;
     background:var(--pink); color:#fff; font:700 15px inherit; margin-top:6px;
   }
   .dock .go:active { transform:scale(.98); }
   .dock-shots { display:flex; gap:8px; overflow-x:auto; margin-top:8px; }
   .dock-shots img { height:56px; border-radius:8px; flex:0 0 auto; }
   .tabs { gap:4px; }

   .spaces {
     display:flex; gap:6px; margin:6px 12px 0;
   }
   .space {
     flex:1; min-height:52px; border-radius:14px; border:1px solid var(--line);
     background:#1c1c26; color:var(--dim); text-align:left; padding:8px 10px;
     font:inherit;
   }
   .space b { display:block; color:var(--text); font-size:14px; }
   .space span { display:block; font-size:11px; margin-top:2px; }
   .space.on { border-color:var(--cyan); background:var(--on); color:var(--text); }
   body.space-kenji .space.on { border-color:#7b3fe4; }

   #view-kenji { display:none; flex:1; min-height:0; flex-direction:column; overflow:hidden; }
   #view-kenji.on { display:flex; }
   .k-top {
     display:flex; align-items:center; gap:8px; margin:8px 12px 6px;
   }
   .k-logo {
     width:42px; height:42px; border-radius:12px; flex:0 0 42px;
     background:#2a2a32; color:#ff4d4d; font:800 22px/42px inherit; text-align:center;
   }
   .k-search {
     flex:1; height:42px; border-radius:12px; border:1px solid var(--line);
     background:#1a1a20; color:var(--text); padding:0 12px; font:inherit;
   }
   .k-grid {
     flex:1; overflow:auto; padding:4px 10px 96px;
     display:grid; grid-template-columns:repeat(auto-fill, minmax(132px, 1fr));
     gap:12px; align-content:start;
   }
   .k-tile {
     border:0; background:transparent; padding:0; color:inherit; text-align:left;
   }
   .k-cover {
     width:100%; aspect-ratio:1; border-radius:16px; overflow:hidden;
     background:linear-gradient(160deg,#2a1630,#16222a);
     display:flex; align-items:center; justify-content:center;
     color:var(--pink); font-size:28px; font-weight:700;
   }
   .k-cover img { width:100%; height:100%; object-fit:cover; display:block; }
   .k-tile .nm {
     margin-top:6px; font-size:12px; font-weight:600;
     white-space:nowrap; overflow:hidden; text-overflow:ellipsis;
   }
   .k-add {
     border:1px dashed var(--line); border-radius:16px;
     aspect-ratio:1; display:flex; flex-direction:column;
     align-items:center; justify-content:center;
     color:var(--dim); font-size:13px; background:#16161c;
   }
   .k-add b { font-size:32px; font-weight:400; color:var(--text); }
   .k-bar {
     position:absolute; left:12px; right:12px; bottom:14px;
     display:flex; gap:8px; align-items:center;
     border:1px solid var(--line); border-radius:12px;
     background:#16161c; padding:8px 10px; font-size:12px; color:var(--dim);
     z-index:4;
   }
   .k-bar button { flex:0 0 auto; }
   body.space-kenji #view-launch, body.space-kenji #view-games { display:none !important; }
   body.space-kenji .tabs { display:none; }

   @media (orientation: landscape) {
     body { padding-top:28px; }
     header { padding:2px 10px 0; }
     header h1 { font-size:18px; }
     .tabs { margin:4px 10px 0; }
     .tab { height:30px; font-size:13px; }
     #view-launch { flex-direction:row; align-items:stretch; }
     .rail-wrap { flex:0 0 36%; max-width:320px; min-height:0; }
     .rail { padding:6px 44px; }
     .slide {
       flex:0 0 min(28vh, 180px); width:min(28vh, 180px); height:min(28vh, 180px);
     }
     .dock { flex:1; margin:6px 10px 8px 0; max-height:none; }
     .navb { width:34px; height:34px; font-size:18px; line-height:34px; }
     .dock h2 { font-size:16px; }
     .dock .go { height:40px; }
   }
 </style>
 </head>
 <body>
 <div class="boot" id="boot">
   <svg class="mark" viewBox="0 0 108 108" aria-hidden="true">
     <circle cx="54" cy="54" r="22" fill="none" stroke="#3EE0D4" stroke-width="4.5"/>
     <path fill="#FF2D78" d="M54 32l12 38-12-8-12 8z"/>
     <circle cx="54" cy="54" r="5" fill="#ececf4"/>
   </svg>
   <p>Symbiosis</p>
 </div>
 <header>
   <h1>
     <svg viewBox="0 0 108 108" aria-hidden="true">
       <circle cx="54" cy="54" r="22" fill="none" stroke="#3EE0D4" stroke-width="4.5"/>
       <path fill="#FF2D78" d="M54 32l12 38-12-8-12 8z"/>
       <circle cx="54" cy="54" r="5" fill="#ececf4"/>
     </svg>
     Symbiosis
   </h1>
   <button class="iconbtn" id="btn-engines">Ядра</button>
   <button class="iconbtn" id="btn-plugins">Плагины</button>
   <button class="iconbtn" id="btn-reload" title="Обновить интерфейс">↻</button>
   <button class="iconbtn" id="btn-tools">Утилиты</button>
   <button class="iconbtn" id="btn-settings">Настройки</button>
 </header>
 <div class="spaces" id="spaces">
   <button class="space on" id="sp-symbiosis" data-id="symbiosis" type="button">
     <b>Symbiosis</b><span>основное ядро · наша оболочка</span>
   </button>
   <button class="space" id="sp-kenji" data-id="kenji" type="button">
     <b>Kenji-NX</b><span>их оболочка · ядро или их APK</span>
   </button>
 </div>
 <div class="tabs">
   <button class="tab on" id="tab-launch">Лаунчер</button>
   <button class="tab" id="tab-games">Список</button>
   <button class="tab" id="tab-conv">Конвертер</button>
 </div>
 <div class="view on" id="view-launch">
   <div class="rail-wrap">
     <button class="navb l" id="ln-prev" type="button">‹</button>
     <div class="rail" id="rail"></div>
     <button class="navb r" id="ln-next" type="button">›</button>
   </div>
   <div class="dock" id="dock"><div class="empty">нет игр</div></div>
 </div>
 <div class="view" id="view-games">
 <div class="search">
   <span style="color:var(--cyan)">⌕</span>
   <input id="q" placeholder="Найти игру…" autocomplete="off">
 </div>
 <div class="tools" id="tools">
   <button data-sort="name" class="on">Имя</button>
   <button data-sort="recent">Недавно</button>
   <button data-sort="play">Время</button>
   <button data-filter="all" class="on">Все</button>
   <button data-filter="save">Сейв</button>
   <button data-filter="mod">Мод</button>
   <button data-filter="fresh">Не играли</button>
 </div>
 <div class="status" id="status">
   <div class="line" id="status-line">Ключи · Прошивка · Игры</div>
   <div class="chips" id="chips"></div>
   <div class="line" id="mem" style="margin-top:6px;font-weight:400"></div>
 </div>
 <div class="list" id="list"><div class="empty">загрузка…</div></div>
 <div class="fabs">
   <button class="fab ghost" id="fab-saves">Сейвы</button>
   <button class="fab" id="fab">＋ Папка</button>
 </div>
 <div class="bar" id="bar">папка не выбрана</div>
 </div>

 <div class="view" id="view-kenji">
   <div class="k-top">
     <div class="k-logo" aria-hidden="true">R</div>
     <input class="k-search" id="k-q" placeholder="Search…" autocomplete="off">
     <button class="iconbtn" id="k-gear" title="Настройки">⚙</button>
   </div>
   <div class="k-grid" id="k-grid"><div class="empty">нет игр</div></div>
   <div class="k-bar" id="k-bar">
     <span id="k-status">пространство Kenji</span>
     <button class="ghost" id="k-dl">Скачать ядро</button>
     <button class="ghost" id="k-ext">Их APK</button>
     <button class="ghost" id="k-plug">Встроить оболочку</button>
   </div>
 </div>
 <div class="view" id="view-conv">
   <div class="status" style="margin-top:10px">
     <div class="line">NSZ · XCZ · NCZ → NSP / NCA</div>
     Сжатый файл не запускается. После конвертации — обложка и «Запустить» или «Удалить».
   </div>
   <div class="conv-list" id="conv-list"><div class="empty">добавьте файл</div></div>
   <div class="fabs">
     <button class="fab" id="fab-conv">＋ Файл</button>
   </div>
 </div>

 <div class="sheet" id="sheet">
   <div class="box">
     <h2 id="sheet-title">Игра</h2>
     <div class="note" id="sheet-note"></div>
     <div class="row" style="margin-top:12px" id="sheet-actions"></div>
   </div>
 </div>

 <script>
 'use strict';
 const $ = id => document.getElementById(id);
 const esc = s => String(s??'').replace(/&/g,'&amp;').replace(/</g,'&lt;');
 const N = () => window.Symbiosis || null;
 function call(name, ...a) {
   try { const n=N(); return n && n[name] ? n[name](...a) : null; } catch(e) { return null; }
 }
