 function launchWithEngine(id) {
   const r = parse(call('selectEngine', id), { message: 'нет моста' });
   if (!r.ok) {
     openEnginesSheet(r.message || 'ядро не выбралось');
     paintCores();
     if (r.needDownload) startEngineDownload(id);
     return;
   }
   const g = RAIL_LIST[LAUNCH_I] || GAMES[0];
   if (g && g.path && N() && N().launch) {
     closeSheet();
     paintCores();
     N().launch(g.path, g.title || '');
     return;
   }
   openEnginesSheet((r.message || 'ядро выбрано') + ' · откройте игру на лаунчере и нажмите Запустить');
   paintCores();
 }

