 function fillDockShots(g) {
   const box = $('dock-shots');
   if (!box || !g) return;
   const data = parse(call('shots', g.path, g.title || ''), { items: [] });
   const items = (data.items || []).slice(0, 8);
   if (!items.length) {
     box.innerHTML = g.lastShot ? '' : '<div class="note" style="margin:0">скринов нет — выйдите из игры один раз</div>';
     if (g.lastShot) {
