 function showTab(id) {
   ['launch','games','conv'].forEach(k => {
     const tab = $('tab-' + k), view = $('view-' + k);
     if (tab) tab.classList.toggle('on', k === id);
     if (view) view.classList.toggle('on', k === id);
   });
   if (id === 'conv') loadConverter();
   if (id === 'launch') {
     if (!$('rail') || !$('rail').children.length) renderLauncher();
     else {
       const el = $('rail').querySelector('.slide.on');
       if (el) el.scrollIntoView({ inline: 'center', block: 'nearest', behavior: 'auto' });
     }
   }
   try { localStorage.setItem('eden-tab', id); } catch (e) {}
 }

 function loadConverter() {
   const data = parse(call('converterItems'), { items: [] });
   const items = data.items || [];
   if (!items.length) {
     $('conv-list').innerHTML = '<div class="empty">Нет файлов. «＋ Файл» — nsz, xcz, ncz или уже готовый nsp/xci.</div>';
     return;
   }
   $('conv-list').innerHTML = items.map((it, i) => {
     const can = !!it.canLaunch;
     const btn = can
       ? `<button class="go" data-act="play" data-i="${i}">Запустить</button>`
       : `<button class="ghost" data-act="del" data-i="${i}">Удалить</button>`;
     return `<div class="card">
       <div class="thumb" id="cv-${i}">▶</div>
       <div class="meta">
         <div class="title">${esc(it.title || it.name || 'файл')}</div>
         <div class="sub ${can ? 'ok' : 'bad'}">${can ? 'можно открыть' : esc(it.reason || 'не открывается')} · ${esc(it.size || '')}</div>
       </div>
       ${btn}
     </div>`;
   }).join('');
   $('conv-list').querySelectorAll('button[data-act]').forEach(b => {
     const it = items[+b.dataset.i];
     b.onclick = ev => {
       ev.stopPropagation();
       if (b.dataset.act === 'play') {
         if (it && it.path && N() && N().launch) N().launch(it.path, it.title || '');
       } else {
         parse(call('deleteConverted', it.path), null);
         loadConverter();
       }
     };
   });
   items.forEach((it, i) => {
     if (!it.canLaunch || !it.path) return;
     setTimeout(() => {
       const el = $('cv-' + i);
       if (!el || !N() || typeof N().icon !== 'function') return;
       const b64 = call('icon', it.path);
       if (b64) el.innerHTML = '<img alt="" src="data:image/jpeg;base64,' + b64 + '">';
     }, 40 * i);
   });
 }

