 function nearestSlide() {
   const rail = $('rail');
   if (!rail) return;
   const mid = rail.scrollLeft + rail.clientWidth / 2;
   let best = 0, dist = 1e9;
   rail.querySelectorAll('.slide').forEach(el => {
     const c = el.offsetLeft + el.offsetWidth / 2;
     const d = Math.abs(c - mid);
     if (d < dist) { dist = d; best = +el.dataset.ri; }
   });
   if (best !== LAUNCH_I) {
     LAUNCH_I = best;
     rail.querySelectorAll('.slide').forEach(el => el.classList.toggle('on', +el.dataset.ri === LAUNCH_I));
     paintDock();
   }
 }

