   if (it.state === 'missing' || it.state === 'broken') {
     btns.push('<button class="ghost e-dl" data-id="' + esc(it.id) + '">Скачать</button>');
   }
   if (it.state === 'ready') {
     btns.push('<button class="ghost e-probe" data-id="' + esc(it.id) + '">Проверить</button>');
   }
   if (it.usable && !it.selected) {
     btns.push('<button class="ghost e-sel" data-id="' + esc(it.id) + '">Выбрать</button>');
   }
   if (it.usable) {
