 function fillDockShots(g) {
   const box = $('dock-shots');
   if (!box || !g) return;
   const data = parse(call('shots', g.path, g.title || ''), { items: [] });
   const items = (data.items || []).slice(0, 8);
   if (!items.length) {
     box.innerHTML = g.lastShot ? '' : '<div class="note" style="margin:0">скринов нет — выйдите из игры один раз</div>';
     if (g.lastShot) {
       const img = document.createElement('img');
       img.alt = '';
       box.appendChild(img);
       const b64 = call('shot', g.lastShot);
       if (b64) img.src = 'data:image/jpeg;base64,' + b64;
     }
     return;
   }
   box.innerHTML = items.map((it, i) => `<img alt="" id="ds-${i}">`).join('');
   items.forEach((it, i) => {
     setTimeout(() => {
       const el = $('ds-' + i);
       if (!el) return;
       const b64 = call('shot', it.path);
       if (b64) el.src = 'data:image/jpeg;base64,' + b64;
     }, 30 * i);
   });
 }

