 function applyPlugins() {
   let p;
   try { p = parse(call('pluginPayload'), null); } catch (e) { return; }
   if (!p) return;
   try {
   const root = document.documentElement;
   Object.keys(p.theme || {}).forEach(k => {
     try { root.style.setProperty(k, p.theme[k]); } catch (e) {}
   });
   let st = document.getElementById('plugin-css');
   if (!st) {
     st = document.createElement('style');
     st.id = 'plugin-css';
     document.head.appendChild(st);
   }
   st.textContent = p.css || '';
   document.querySelectorAll('[data-plugin-hide]').forEach(el => {
     el.style.removeProperty('display');
     el.removeAttribute('data-plugin-hide');
   });
   (p.hide || []).forEach(sel => {
     try {
       document.querySelectorAll(sel).forEach(el => {
         el.setAttribute('data-plugin-hide', '1');
         el.style.display = 'none';
       });
     } catch (e) {}
   });
   document.querySelectorAll('[data-plugin-html]').forEach(el => el.remove());
   (p.html || []).forEach(item => {
     const at = String(item.at || '');
     const html = item.html || '';
     if (!at || !html) return;
     try {
       const wrap = document.createElement('div');
       wrap.setAttribute('data-plugin-html', '1');
       wrap.innerHTML = html;
       if (at.startsWith('after:')) {
         const t = document.querySelector(at.slice(6));
         if (t && t.parentNode) t.parentNode.insertBefore(wrap, t.nextSibling);
       } else if (at.startsWith('before:')) {
         const t = document.querySelector(at.slice(7));
         if (t && t.parentNode) t.parentNode.insertBefore(wrap, t);
       } else {
         const t = document.querySelector(at);
         if (t) t.appendChild(wrap);
       }
     } catch (e) {}
   });
   const strings = p.strings || {};
   if (strings['Search games…'] && $('q')) $('q').placeholder = strings['Search games…'];
   } catch (e) {}
 }

