     const name = 'пресет ' + new Date().toLocaleString('ru-RU');
     const r = parse(call('savePreset', name), { message: 'нет моста' });
     $('sheet-note').textContent = r.message || name;
     drawPresets();
   };
   drawPresets();
   $('a-data').onclick = () => { if (N() && N().pickDataRoot) N().pickDataRoot(); };
   $('a-saves').onclick = () => { pickSaves(); };
   $('a-saves-off').onclick = () => {
     if (N() && N().clearSavesFolder) N().clearSavesFolder();
     SAVES = { path:'', titles:0 };
     loadGames(); loadStatus();
     $('sheet-note').textContent = 'папка сейвов сброшена';
   };
   $('a-utils').onclick = () => { closeSheet(); if (N() && N().openUtilities) N().openUtilities(); };
   $('a-close').onclick = closeSheet;
   $('sheet-note').querySelectorAll('.sw').forEach(btn => {
     btn.onclick = ev => {
       ev.stopPropagation();
       const now = !btn.classList.contains('on');
       const r = parse(call('setBool', btn.dataset.key, now), { message: 'нет моста' });
       $('bar').textContent = r.message || '';
       openSettingsSheet();
     };
   });
   const rd = $('res-down'), ru = $('res-up');
   const cur = (live && typeof live.resolution === 'number') ? live.resolution : 3;
   if (rd) rd.onclick = () => { parse(call('setResolution', Math.max(0, cur - 1)), {}); openSettingsSheet(); };
   if (ru) ru.onclick = () => { parse(call('setResolution', Math.min(3, cur + 1)), {}); openSettingsSheet(); };
   openSheet();
 }

 function drawPresets() {
   const box = $('sheet-note');
   if (!box) return;
   const data = parse(call('presets'), { items: [] });
   const items = data.items || [];
   let html = box.innerHTML;
   if (items.length) {
     html += '<div style="margin-top:10px;font-weight:600">Пресеты</div>';
     items.forEach(it => {
       html += '<div class="plug"><div class="nm"><b>' + esc(it.name) + '</b> · ' + (it.keys || 0) +
         '</div><button class="ghost p-ap">Вкл</button><button class="ghost p-rm">Снести</button></div>';
     });
     box.innerHTML = html;
     box.querySelectorAll('.plug').forEach((el, i) => {
       const it = items[i];
       const ap = el.querySelector('.p-ap');
       const rm = el.querySelector('.p-rm');
       if (ap) ap.onclick = ev => { ev.stopPropagation(); const r = parse(call('applyPreset', it.name), {}); $('sheet-note').textContent = r.message || ''; };
       if (rm) rm.onclick = ev => { ev.stopPropagation(); parse(call('removePreset', it.name), {}); openSettingsSheet(); };
     });
   }
 }

 function onConvertQueue(q) {
   showTab('conv');
   const note = (q && q.note) || '';
   const busy = !!(q && q.busy);
   let banner = '';
   if (busy || note) {
     banner = '<div class="status"><div class="line">' + esc(note || 'очередь') + '</div>' +
       (busy ? 'не трогайте телефон' : '') + '</div>';
   }
   loadConverter();
   if (banner) $('conv-list').insertAdjacentHTML('afterbegin', banner);
 }

 function showTab(id) {
   ['launch','games','conv'].forEach(k => {
     const tab = $('tab-' + k), view = $('view-' + k);
     if (tab) tab.classList.toggle('on', k === id);
     if (view) view.classList.toggle('on', k === id);
   });
   if (id === 'conv') loadConverter();
   if (id === 'launch') {
     if (!$('rail') || !$('rail').children.length) renderLauncher();
     else {
       const el = $('rail').querySelector('.slide.on');
       if (el) el.scrollIntoView({ inline: 'center', block: 'nearest', behavior: 'auto' });
     }
   }
   try { localStorage.setItem('eden-tab', id); } catch (e) {}
 }

 function loadConverter() {
   const data = parse(call('converterItems'), { items: [] });
   const items = data.items || [];
   if (!items.length) {
     $('conv-list').innerHTML = '<div class="empty">Нет файлов. «＋ Файл» — nsz, xcz, ncz или уже готовый nsp/xci.</div>';
     return;
   }
   $('conv-list').innerHTML = items.map((it, i) => {
     const can = !!it.canLaunch;
     const btn = can
       ? `<button class="go" data-act="play" data-i="${i}">Запустить</button>`
       : `<button class="ghost" data-act="del" data-i="${i}">Удалить</button>`;
     return `<div class="card">
       <div class="thumb" id="cv-${i}">▶</div>
       <div class="meta">
         <div class="title">${esc(it.title || it.name || 'файл')}</div>
         <div class="sub ${can ? 'ok' : 'bad'}">${can ? 'можно открыть' : esc(it.reason || 'не открывается')} · ${esc(it.size || '')}</div>
       </div>
       ${btn}
     </div>`;
   }).join('');
   $('conv-list').querySelectorAll('button[data-act]').forEach(b => {
     const it = items[+b.dataset.i];
     b.onclick = ev => {
       ev.stopPropagation();
       if (b.dataset.act === 'play') {
         if (it && it.path && N() && N().launch) N().launch(it.path, it.title || '');
       } else {
         parse(call('deleteConverted', it.path), null);
         loadConverter();
       }
     };
   });
   items.forEach((it, i) => {
     if (!it.canLaunch || !it.path) return;
     setTimeout(() => {
       const el = $('cv-' + i);
       if (!el || !N() || typeof N().icon !== 'function') return;
       const b64 = call('icon', it.path);
       if (b64) el.innerHTML = '<img alt="" src="data:image/jpeg;base64,' + b64 + '">';
     }, 40 * i);
   });
 }

 function onConverted(info) {
   showTab('conv');
   loadConverter();
   if (info && info.message) {
     const note = document.createElement('div');
     note.className = 'status';
     note.innerHTML = '<div class="line">' + esc(info.message) + '</div>' +
       (info.reason && !info.canLaunch ? esc(info.reason) : '');
     $('conv-list').prepend(note);
   }
 }

 $('tab-launch').onclick = () => showTab('launch');
 $('tab-games').onclick = () => showTab('games');
 $('tab-conv').onclick = () => showTab('conv');
 $('fab-conv').onclick = () => { if (N() && N().pickConvert) N().pickConvert(); };


 function paintTools() {
   const bar = $('tools');
   if (!bar) return;
   bar.querySelectorAll('[data-sort]').forEach(b => b.classList.toggle('on', b.dataset.sort === SORT));
   bar.querySelectorAll('[data-filter]').forEach(b => b.classList.toggle('on', b.dataset.filter === FILTER));
 }
 const toolsEl = $('tools');
 if (toolsEl) {
   toolsEl.addEventListener('click', ev => {
     const b = ev.target.closest('button');
     if (!b) return;
     if (b.dataset.sort) { SORT = b.dataset.sort; localStorage.setItem('eden-sort', SORT); }
     if (b.dataset.filter) { FILTER = b.dataset.filter; localStorage.setItem('eden-filter', FILTER); }
     paintTools();
     render();
     renderLauncher();
   });
   paintTools();
 }


 const railEl = $('rail');
 if (railEl) {
   let st = 0;
   railEl.addEventListener('scroll', () => {
     clearTimeout(st);
     st = setTimeout(nearestSlide, 80);
   }, {passive:true});
 }

 function keepLaunchFrame() {
   const rail = $('rail');
   if (!rail) return;
   const el = rail.querySelector('.slide.on');
   if (el) el.scrollIntoView({ inline: 'center', block: 'nearest', behavior: 'auto' });
 }
 let rotT = 0;
 window.addEventListener('resize', () => {
   clearTimeout(rotT);
   rotT = setTimeout(keepLaunchFrame, 40);
 });
 window.addEventListener('orientationchange', () => {
   keepLaunchFrame();
   setTimeout(keepLaunchFrame, 80);
 });

 if ($('ln-prev')) $('ln-prev').onclick = () => snapTo(LAUNCH_I - 1);
 if ($('ln-next')) $('ln-next').onclick = () => snapTo(LAUNCH_I + 1);

 let SPACE = 'symbiosis';

 function paintSpaces(info) {
   const data = info || parse(call('spaces'), { current: SPACE, items: [] });
   SPACE = data.current || 'symbiosis';
   document.body.classList.toggle('space-kenji', SPACE === 'kenji');
   ['symbiosis', 'kenji'].forEach(id => {
     const el = $('sp-' + id);
     if (el) el.classList.toggle('on', SPACE === id);
   });
   const kenji = (data.items || []).find(it => it.id === 'kenji') || {};
   const off = data.official || {};
   const spk = $('sp-kenji');
   if (spk) {
     const sub = spk.querySelector('span');
     if (sub) {
       sub.textContent = off.installed
         ? ('их APK «' + (off.label || 'Kenji') + '» · оболочка здесь')
         : (kenji.ready ? 'ядро скачано · наш плеер' : 'скачайте ядро или поставьте их APK');
     }
   }
   const kv = $('view-kenji');
   if (kv) kv.classList.toggle('on', SPACE === 'kenji');
   if (SPACE === 'kenji') {
     renderKenjiGrid();
     paintKenjiBar(data);
   }
 }

 function paintKenjiBar(data) {
   const st = $('k-status');
   const dl = $('k-dl');
   const ext = $('k-ext');
   if (!st) return;
   const off = (data && data.official) || {};
   const core = data && data.kenjiCore;
   if (off.installed) {
     st.textContent = 'их APK «' + (off.label || 'Kenji') + '» · игры уходят туда';
   } else if (core === 'ready') {
     st.textContent = 'их APK нет · наш плеер в :kenji';
   } else if (core === 'broken') {
     st.textContent = 'файл ядра битый — скачайте снова';
   } else {
     st.textContent = 'нет ядра и нет их APK — скачайте или поставьте Kenji';
   }
   if (dl) dl.style.display = (core === 'ready') ? 'none' : '';
   if (ext) {
     ext.textContent = off.installed ? 'Открыть их APK' : 'Их APK не стоит';
     ext.disabled = !off.installed;
   }
 }

 function renderKenjiGrid() {
   const box = $('k-grid');
   if (!box) return;
   const q = (($('k-q') && $('k-q').value) || '').trim().toLowerCase();
   const list = (q ? GAMES.filter(g => (g.title || '').toLowerCase().includes(q)) : GAMES.slice());
   const add = '<button class="k-add" id="k-add" type="button"><b>+</b>папка</button>';
   if (!list.length) {
     box.innerHTML = add + '<div class="empty" style="grid-column:1/-1">нет игр — добавьте папку</div>';
     const a = $('k-add');
     if (a) a.onclick = () => { if (N() && N().pickFolder) N().pickFolder(); };
     return;
   }
   box.innerHTML = add + list.map(g => {
     const i = GAMES.indexOf(g);
     return '<button class="k-tile" data-i="' + i + '" type="button">' +
       '<div class="k-cover" id="kc-' + i + '">▶</div>' +
       '<div class="nm">' + esc(g.title || 'без имени') + '</div></button>';
   }).join('');
   const a = $('k-add');
   if (a) a.onclick = () => { if (N() && N().pickFolder) N().pickFolder(); };
   box.querySelectorAll('.k-tile').forEach(el => {
     const g = GAMES[+el.dataset.i];
     el.onclick = () => play(g);
   });
   list.forEach(g => {
     const i = GAMES.indexOf(g);
     setTimeout(() => {
       const el = $('kc-' + i);
       if (!el) return;
       const b64 = call('cover', g.path) || call('icon', g.path);
       if (b64) el.innerHTML = '<img alt="" src="data:image/jpeg;base64,' + b64 + '">';
     }, 30 * Math.max(0, list.indexOf(g)));
   });
 }

 function applySpace(id) {
   if (!N() || !N().selectSpace) {
     SPACE = id;
     paintSpaces({ current: id, items: [] });
     return;
   }
   const r = parse(call('selectSpace', id), { message: 'нет моста' });
   applyPlugins();
   paintSpaces();
   if (r && r.message) {
     const bar = $('k-status') || $('bar');
     if (bar) bar.textContent = r.message;
   }
 }

 function loadSpaces() {
   paintSpaces();
 }

 $('q').addEventListener('input', render);
 $('fab').onclick = () => { if (N() && N().pickFolder) N().pickFolder(); };
 $('fab-saves').onclick = pickSaves;
 $('btn-engines').onclick = () => openEnginesSheet();
 $('btn-tools').onclick = () => { if (N() && N().openUtilities) N().openUtilities(); };
 $('btn-settings').onclick = openSettingsSheet;
 $('btn-plugins').onclick = openPluginsSheet;
 $('btn-reload').onclick = reloadUi;
 if ($('sp-symbiosis')) $('sp-symbiosis').onclick = () => applySpace('symbiosis');
 if ($('sp-kenji')) $('sp-kenji').onclick = () => applySpace('kenji');
 if ($('k-q')) $('k-q').addEventListener('input', renderKenjiGrid);
 if ($('k-gear')) $('k-gear').onclick = openSettingsSheet;
 if ($('k-dl')) $('k-dl').onclick = () => startEngineDownload('kenji');
 if ($('k-ext')) $('k-ext').onclick = () => {
   const g = RAIL_LIST[LAUNCH_I] || GAMES[0] || { path: '', title: '' };
   const r = parse(call('openOfficialKenji', g.path || ''), { message: 'нет моста' });
   const st = $('k-status');
   if (st) st.textContent = r.message || '';
 };
 if ($('k-plug')) $('k-plug').onclick = () => {
   const r = parse(call('installKenjiShell'), { message: 'нет моста' });
   applyPlugins();
   paintSpaces();
   const st = $('k-status');
   if (st) st.textContent = r.message || 'оболочка';
 };
 $('sheet').addEventListener('click', e => { if (e.target.id === 'sheet') closeSheet(); });

 if ('serviceWorker' in navigator) navigator.serviceWorker.register('sw.js').catch(()=>{});
 loadGames();
 loadStatus();
 applyPlugins();
 loadSpaces();
 setTimeout(() => { const b = $('boot'); if (b) b.classList.add('go'); }, 700);
 setTimeout(() => { const b = $('boot'); if (b) b.remove(); }, 1200);
 try {
   const tab = localStorage.getItem('eden-tab') || 'launch';
   if (tab === 'games' || tab === 'conv' || tab === 'launch') showTab(tab);
 } catch (e) {}

 </script>
 </body>
 </html>

