function fillCover(gi, path) {
  const el = $('cvl-' + gi);
  if (!el || !path) return;
  const fn = (N() && typeof N().cover === 'function') ? 'cover' : 'icon';
  const b64 = call(fn, path);
  if (b64) el.innerHTML = '<img alt="" src="data:image/jpeg;base64,' + b64 + '">';
}

function snapTo(i) {
  if (!RAIL_LIST.length) return;
  const n = RAIL_LIST.length;
  LAUNCH_I = ((i % n) + n) % n;
  const rail = $('rail');
  if (!rail) return;
  rail.querySelectorAll('.slide').forEach(el => el.classList.toggle('on', +el.dataset.ri === LAUNCH_I));
  const el = rail.querySelector('.slide.on');
  if (el) el.scrollIntoView({ inline: 'center', block: 'nearest', behavior: 'smooth' });
  paintDock();
}

function nearestSlide() {
  const rail = $('rail');
  if (!rail) return;
  const mid = rail.scrollLeft + rail.clientWidth / 2;
  let best = 0, dist = 1e9;
  rail.querySelectorAll('.slide').forEach(el => {
    const c = el.offsetLeft + el.offsetWidth / 2;
    const d = Math.abs(c - mid);
    if (d < dist) { dist = d; best = +el.dataset.ri; }
  });
  if (best !== LAUNCH_I) {
    LAUNCH_I = best;
    rail.querySelectorAll('.slide').forEach(el => el.classList.toggle('on', +el.dataset.ri === LAUNCH_I));
    paintDock();
  }
}

