#!/usr/bin/env python3
"""Build a runnable copy of docs/library.html with a stubbed Symbiosis bridge
and a diagnostics block, so the launcher rail can be measured for real."""
import json
import sys
from pathlib import Path

SRC = Path("/home/runner/hub-work/symbiosis/code/docs/library.html")
OUT = Path("/home/runner/hub-work/symbiosis/tmp/run.html")

GAMES = [
    {
        "path": f"/games/game{i}.nsp",
        "title": f"Игра номер {i}",
        "developer": "Studio",
        "titleId": f"0100{i:04d}",
        "fileSize": "4.1 GB",
        "version": "1.0",
        "hasSave": i % 3 == 0,
        "saveSize": "12 MB" if i % 3 == 0 else "",
        "shots": i,
        "shaderSize": "0 B",
        "addons": [],
        "playSeconds": i * 60,
        "lastPlayed": 1756000000 + i,
        "lastPlayedLabel": "вчера",
    }
    for i in range(1, 9)
]

BRIDGE = """
<script>
window.Symbiosis = {
  games: () => JSON.stringify({games: %s}),
  status: () => JSON.stringify({items: [{label:'Ключи',present:true},{label:'Прошивка',present:true},{label:'Игры',present:true}]}),
  folders: () => JSON.stringify({folders: [{name:'игры', uri:'content://x', games: 8, size:'32 GB'}]}),
  saves: () => JSON.stringify({}),
  saveSource: () => JSON.stringify({path:'',titles:0,name:'',size:''}),
  spaces: () => JSON.stringify({current:'symbiosis', items:[{id:'symbiosis'},{id:'kenji'}], official:{}}),
  engines: () => JSON.stringify({current:'eden', launch:'eden', currentLabel:'Eden', launchLabel:'Eden'}),
  settings: () => JSON.stringify({cpuLabel:''}),
  converterItems: () => JSON.stringify({items: []}),
  plugins: () => JSON.stringify({items: []}),
  status_: () => null
};
</script>
""" % json.dumps(GAMES, ensure_ascii=False)

DIAG = """
<script>
function diag() {
  const out = {};
  const rail = document.getElementById('rail');
  const view = document.getElementById('view-launch');
  const wrap = document.querySelector('.rail-wrap');
  if (!rail) { out.error = 'no rail'; return out; }
  const slides = [...rail.querySelectorAll('.slide')];
  out.slides = slides.length;
  out.railClientWidth = Math.round(rail.clientWidth);
  out.railScrollWidth = Math.round(rail.scrollWidth);
  out.railScrollLeft = Math.round(rail.scrollLeft);
  out.railHeight = Math.round(rail.clientHeight);
  out.viewRect = view ? [Math.round(view.getBoundingClientRect().width), Math.round(view.getBoundingClientRect().height)] : null;
  out.wrapRect = wrap ? [Math.round(wrap.getBoundingClientRect().width), Math.round(wrap.getBoundingClientRect().height)] : null;
  const r = rail.getBoundingClientRect();
  out.slideGeom = slides.map(el => {
    const b = el.getBoundingClientRect();
    return {
      i: el.dataset.ri,
      left: Math.round(b.left - r.left),
      width: Math.round(b.width),
      visiblePx: Math.round(Math.max(0, Math.min(b.right, r.right) - Math.max(b.left, r.left))),
    };
  });
  out.visibleSlides = out.slideGeom.filter(s => s.visiblePx > 0).length;
  out.fullyVisible = out.slideGeom.filter(s => s.visiblePx >= s.width - 2).length;
  // can it scroll at all?
  const before = rail.scrollLeft;
  rail.scrollLeft = before + 500;
  out.scrolledBy = Math.round(rail.scrollLeft - before);
  rail.scrollLeft = 0;
  // what does the dock say
  const dock = document.getElementById('dock');
  out.dockTitle = dock ? (dock.querySelector('h2') || {}).textContent : null;
  out.launchIndex = typeof LAUNCH_I !== 'undefined' ? LAUNCH_I : null;
  out.railListLen = typeof RAIL_LIST !== 'undefined' ? RAIL_LIST.length : null;
  out.gamesLen = typeof GAMES !== 'undefined' ? GAMES.length : null;
  out.filter = typeof FILTER !== 'undefined' ? FILTER : null;
  out.query = (document.getElementById('q') || {}).value;
  out.listRows = document.querySelectorAll('#list .card, #list .row, #list > *').length;
  return out;
}
setTimeout(function () {
  const d = diag();
  const pre = document.createElement('pre');
  pre.id = 'DIAG';
  pre.textContent = JSON.stringify(d, null, 1);
  document.body.appendChild(pre);
}, 900);
</script>
"""

html = SRC.read_text(encoding="utf-8")
marker = "<script>\n'use strict';"
if marker not in html:
    sys.exit("main script marker not found")
html = html.replace(marker, BRIDGE + marker, 1)
html = html.replace("</body>", DIAG + "</body>", 1)
# the service worker would 404 from file://; harmless but noisy
html = html.replace("if ('serviceWorker' in navigator)", "if (false)")
OUT.write_text(html, encoding="utf-8")
print("wrote", OUT)

