#!/usr/bin/env python3
"""Run the launcher-rail scenarios inside library.html itself.

In-page so the real functions (visibleGames/renderLauncher/loadGames) are
exercised, and top-level `let` bindings are reachable without an iframe.
"""
import json
import re
import sys
from pathlib import Path

SRC = Path("/home/runner/hub-work/symbiosis/code/docs/library.html")
OUT = Path("/home/runner/hub-work/symbiosis/tmp/run.html")

GAMES = [
    {
        "path": f"/games/game{i}.nsp",
        "title": f"Игра номер {i}",
        "developer": "Studio",
        "titleId": f"0100{i:04d}",
        "fileSize": "4.1 GB",
        "version": "1.0",
        "hasSave": i == 2,
        "saveSize": "12 MB" if i == 2 else "",
        "shots": i,
        "shaderSize": "0 B",
        "addons": [],
        "playSeconds": i * 60,
        "lastPlayed": 1756000000 + i,
        "lastPlayedLabel": "вчера",
    }
    for i in range(1, 9)
]

BRIDGE = """
<script>
window.Symbiosis = {
  games: () => JSON.stringify({games: %s}),
  status: () => JSON.stringify({items: [{label:'Ключи',present:true},{label:'Прошивка',present:true},{label:'Игры',present:true}]}),
  folders: () => JSON.stringify({folders: [{name:'игры', uri:'content://x', games: 8, size:'32 GB'}]}),
  saveSource: () => JSON.stringify({path:'',titles:0,name:'',size:''}),
  spaces: () => JSON.stringify({current:'symbiosis', items:[{id:'symbiosis'},{id:'kenji'}], official:{}}),
  engines: () => JSON.stringify({current:'eden', launch:'eden', currentLabel:'Eden', launchLabel:'Eden'}),
  settings: () => JSON.stringify({cpuLabel:''}),
  converterItems: () => JSON.stringify({items: []}),
  plugins: () => JSON.stringify({items: []})
};
</script>
""" % json.dumps(GAMES, ensure_ascii=False)

DIAG = """
<script>
function snap(label) {
  const rail = document.getElementById('rail');
  const slides = rail ? [...rail.querySelectorAll('.slide')] : [];
  const list = document.getElementById('list');
  return {
    label,
    games: GAMES.length,
    railSlides: slides.length,
    listRows: list ? list.querySelectorAll('.card, .row, .game').length : -1,
    dockTitle: (document.querySelector('#dock h2') || {}).textContent || null,
    q: document.getElementById('q').value,
    filter: FILTER,
    listFirstTitle: (document.querySelector('#list .title') || {}).textContent || null
  };
}
function scenario(label, fn) {
  fn();
  loadGames();          // what returning from a game / rescan does
  return snap(label);
}
setTimeout(function () {
  const report = [];
  report.push(scenario('1 чисто, без фильтра', () => {
    document.getElementById('q').value = ''; FILTER = 'all';
  }));
  report.push(scenario('2 в «Списке» набрали "номер 3"', () => {
    document.getElementById('q').value = 'номер 3';
  }));
  report.push(scenario('3 фильтр «Сейв» (игра одна)', () => {
    document.getElementById('q').value = ''; FILTER = 'save';
  }));
  report.push(scenario('4 фильтр «Не играли»', () => { FILTER = 'fresh'; }));
  report.push(scenario('5 вернулись к «Все»', () => { FILTER = 'all'; }));
  report.push(scenario('6 q остался, фильтр «Все»', () => {
    document.getElementById('q').value = 'номер 3';
  }));
  // what the dock would launch right now
  const dockTarget = RAIL_LIST[LAUNCH_I] ? RAIL_LIST[LAUNCH_I].title : null;
  const pre = document.createElement('pre');
  pre.id = 'DIAG';
  pre.textContent = JSON.stringify({report: report, dockLaunches: dockTarget,
    railHasCounter: !!document.querySelector('#dock [id*=count], #dock .count')}, null, 1);
  document.body.appendChild(pre);
}, 900);
</script>
"""

html = SRC.read_text(encoding="utf-8")
marker = "<script>\n'use strict';"
if marker not in html:
    sys.exit("main script marker not found")
html = html.replace(marker, BRIDGE + marker, 1)
html = html.replace("</body>", DIAG + "</body>", 1)
html = html.replace("if ('serviceWorker' in navigator)", "if (false)")
OUT.write_text(html, encoding="utf-8")
print("wrote", OUT)

